import re
from collections import Counter, defaultdict

# заголовок -> id (мой диапазон)
zag2id = {}
for line in open('skelet-vladelca.tsv', encoding='utf-8'):
    if line.startswith('#'): continue
    f = line.rstrip('\n').split('\t')
    if 'V0001' <= f[0] <= 'V0345':
        zag2id.setdefault(f[2], []).append(f[0])

yarus = {}
for line in open('verdikt-vladelca.tsv', encoding='utf-8'):
    if line.startswith('#') or not line.strip(): continue
    f = line.rstrip('\n').split('\t')
    if 'V0001' <= f[0] <= 'V0345':
        yarus[f[0]] = f[1] + ('/' + f[2] if f[1] == '1' else '')

txt = open('KRATNOST-vladelca.md', encoding='utf-8').read()
blocks = re.split(r'^### (\d+)\. (.+?) — (\d+) вхожден\w*$', txt, flags=re.M)
groups = []
for i in range(1, len(blocks), 4):
    num, name, cnt, body = blocks[i], blocks[i+1], blocks[i+2], blocks[i+3]
    zags = re.findall(r'^- \*\*(.+?)\*\* — `', body, flags=re.M)
    groups.append((int(num), name, int(cnt), zags))

print(f"групп разобрано: {len(groups)} · сумма вхождений: {sum(g[2] for g in groups)}")
matched = 0
rows = []
for num, name, cnt, zags in groups:
    ys = []
    for z in zags:
        for gid in zag2id.get(z, []):
            if gid in yarus:
                ys.append((gid, yarus[gid])); matched += 1
    if ys:
        c = Counter(y for _, y in ys)
        top, topn = c.most_common(1)[0]
        rows.append((len(ys), num, name, topn/len(ys), dict(c)))
print(f"записей моего диапазона нашлось в группах: {matched} из 345")
rows.sort(key=lambda r: -r[0])
print("\nгруппа | моих записей | доля главного яруса | раскладка")
for n, num, name, share, c in rows:
    if n >= 4:
        print(f"{num:>2}. {name[:52]:<52} | {n:>3} | {share*100:>4.0f}% | {c}")
# сколько записей НЕ совпали с главным ярусом своей группы
otkl = 0; vsego = 0
for n, num, name, share, c in rows:
    top = max(c.values())
    otkl += n - top; vsego += n
print(f"\nвсего в группах: {vsego} · отклонились от главного яруса своей группы: {otkl} ({100*otkl/vsego:.0f} %)")
